import sys
from itertools import combinations

def orientation(p, q, r):
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if val == 0:
        return 0
    return 1 if val > 0 else 2

def are_collinear(p, q, r):
    return orientation(p, q, r) == 0

def count_intersections(points):
    n = len(points)
    intersections = 0
    for i in range(n):
        for j in range(i + 1, n):
            if not are_collinear(points[i], points[j], points[(i + 1) % n]):
                continue
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    if not are_collinear(points[k], points[l], points[(k + 1) % n]):
                        continue
                    if not are_collinear(points[i], points[j], points[k]) and not are_collinear(points[i], points[j], points[l]):
                        intersections += 1
    return intersections

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    points = []
    index = 1
    for _ in range(n):
        x = int(data[index])
        y = int(data[index + 1])
        points.append((x, y))
        index += 2

    result = count_intersections(points)
    print(result)

if __name__ == "__main__":
    main()

import sys
from itertools import combinations

def cross_product(p1, p2, p3):
    return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

def is_intersect(p1, p2, p3, p4):
    d1 = cross_product(p3, p4, p1)
    d2 = cross_product(p3, p4, p2)
    d3 = cross_product(p1, p2, p3)
    d4 = cross_product(p1, p2, p4)

    return (d1 * d2 < 0) and (d3 * d4 < 0)

def count_intersections(points):
    n = len(points)
    intersections = 0

    for (p1, p2), (p3, p4) in combinations(combinations(points, 2), 2):
        if is_intersect(p1, p2, p3, p4):
            intersections += 1

    return intersections

